const rs = await Promise.allSettled([
  tools.exec_command({cmd:"pwd",workdir:"/app"}),
  tools.exec_command({cmd:"rg --files -g 'AGENTS.md' -g 'go.mod' -g '*chat*' -g '*agent*' -g '*token*' | head -100",workdir:"/app"}),
  tools.exec_command({cmd:"git status --short",workdir:"/app"})
]); rs.forEach((r,i)=>text(JSON.stringify({i,result:r})));

const rs = await Promise.allSettled([
  tools.exec_command({cmd:"find .. -name AGENTS.md -print",workdir:"/app"}),
  tools.exec_command({cmd:"find . -maxdepth 4 -type f \\( -name 'go.mod' -o -name '*chat*' -o -name '*agent*' -o -name '*token*' \\) -print | head -100",workdir:"/app"})
]); rs.forEach((r,i)=>text(JSON.stringify({i,result:r})));

const rs = await Promise.allSettled([
  tools.exec_command({cmd:"find lib/ai -maxdepth 3 -type f -print",workdir:"/app"}),
  tools.exec_command({cmd:"sed -n '1,280p' lib/ai/chat.go",workdir:"/app",max_output_tokens:15000}),
  tools.exec_command({cmd:"sed -n '1,300p' lib/ai/model/agent.go",workdir:"/app",max_output_tokens:15000}),
  tools.exec_command({cmd:"grep -R -n 'TokensUsed\\|PlanAndExecute\\|\\.Complete(ctx' lib/ai --include='*.go'",workdir:"/app",max_output_tokens:15000})
]); rs.forEach((r,i)=>text(JSON.stringify({i,result:r})));

